#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const long long INF = 1e18;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> a(n);
    vector<long long> u(n, INF);

    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (a[i] != -1) {
            u[i] = a[i];
        }
    }

    // Varredura da esquerda para a direita
    for (int i = 1; i < n; ++i) {
        if (u[i - 1] != INF) {
            u[i] = min(u[i], u[i - 1] + 1);
        }
    }

    // Varredura da direita para a esquerda
    for (int i = n - 2; i >= 0; --i) {
        if (u[i + 1] != INF) {
            u[i] = min(u[i], u[i + 1] + 1);
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << u[i] << (i == n - 1 ? "" : " ");
    }
    cout << "\n";

    return 0;
}
